const timesheetDate = $input.first().json.body?.timesheetDate;
if (!timesheetDate) throw new Error('timesheetDate required (M/D/YYYY)');
const parts = timesheetDate.split('/');
if (parts.length !== 3) throw new Error('Invalid format. Use M/D/YYYY');
const month = parseInt(parts[0]).toString().padStart(2, '0');
const day = parseInt(parts[1]).toString().padStart(2, '0');
const year = parts[2];
const formattedDate = year + '.' + month + '.' + day;
const outputPath = '/app/n8n/timesheet/output/' + formattedDate;
const templatePath = '/app/n8n/timesheet/n8n-workflows/templates';
return {json: {timesheetDate: timesheetDate, formattedDate: formattedDate, folderName: formattedDate, outputPath: outputPath, templatePath: templatePath}};

const { execSync } = require('child_process');
const outputPath = $input.first().json.outputPath;
try {
  execSync('rm -rf "' + outputPath + '"');
  const data = $input.first().json;
  return {json: {success: true, folderDeleted: true, timesheetDate: data.timesheetDate, formattedDate: data.formattedDate, folderName: data.folderName, outputPath: outputPath, templatePath: data.templatePath}};
} catch (error) {
  throw new Error('Failed to delete folder: ' + error.message);
}

const { execSync } = require('child_process');
const outputPath = $input.first().json.outputPath;
try {
  execSync('mkdir -p "' + outputPath + '"');
  const data = $input.first().json;
  return {json: {success: true, folderCreated: true, timesheetDate: data.timesheetDate, formattedDate: data.formattedDate, folderName: data.folderName, outputPath: outputPath, templatePath: data.templatePath}};
} catch (error) {
  throw new Error('Failed to create folder: ' + error.message);
}

const { execSync } = require('child_process');
const data = $input.first().json;
const wordTemplatePath = data.templatePath + '/RossNanton-Invoice-yyyy.mm.dd.docx';
const wordOutputPath = data.outputPath + '/RossNanton-Invoice-' + data.formattedDate + '.docx';
try {
  execSync('cp "' + wordTemplatePath + '" "' + wordOutputPath + '"');
  return {json: {success: true, fileCopied: 'Word', outputPath: wordOutputPath, timesheetDate: data.timesheetDate, formattedDate: data.formattedDate, excelOutputPath: data.outputPath + '/RossNanton-Timesheet-' + data.formattedDate + '.xlsx'}};
} catch (error) {
  throw new Error('Failed to copy Word: ' + error.message);
}

const { execSync } = require('child_process');
const data = $input.first().json;
const excelTemplatePath = data.templatePath + '/RossNanton-Timesheet-yyyy.mm.dd.xlsx';
const excelOutputPath = data.outputPath + '/RossNanton-Timesheet-' + data.formattedDate + '.xlsx';
try {
  execSync('cp "' + excelTemplatePath + '" "' + excelOutputPath + '"');
  return {json: {success: true, fileCopied: 'Excel', excelFilePath: excelOutputPath, timesheetDate: data.timesheetDate, formattedDate: data.formattedDate, outputPath: data.outputPath}};
} catch (error) {
  throw new Error('Failed to copy Excel: ' + error.message);
}

const { execSync } = require('child_process');
const data = $input.first().json;
const excelFilePath = data.excelFilePath;
const timesheetDate = data.timesheetDate;
if (!excelFilePath) throw new Error('Excel file path not provided');
if (!timesheetDate) throw new Error('Timesheet date not provided');
try {
  const result = execSync('node /app/n8n/timesheet/n8n-workflows/scripts/update-excel.js "' + excelFilePath + '" E8 "' + timesheetDate + '"', {encoding: 'utf8'});
  const parsed = JSON.parse(result);
  if (!parsed.success) throw new Error(parsed.error);
  return {json: {success: true, fileUpdated: 'Excel', timesheetDate: timesheetDate, formattedDate: data.formattedDate, outputPath: data.outputPath}};
} catch (error) {
  throw new Error('Failed to update Excel: ' + error.message);
}
